def max_value_on_paths(N, grid_values):
    n = len(grid_values)
    g1 = [[0] * N for _ in range(N)]  # grid1 will hold the values that are collected by the first path
    g2 = [[0] * N for _ in range(N)]  # grid2 will hold the values that are collected by the second path

    # Initialize the first path
    x, y = 0, 0
    for (i, j, v) in grid_values:
        g1[x][y] = v
        x, y = i + 1, j + 1

    # Sort grid_values by value and use the top N values to fill g1
    sorted_grid_values = sorted(grid_values, key=lambda el: el[2], reverse=True)
    g1 = sorted_grid_values[:N]

    # Initialize the second path
    x, y = 0, 0
    for (i, j, v) in g1:
        if grid_values[(i, j, v) == (x, y, g1) == g1:
            g2[x][y] = g1[x][y]
            x, y = i + 1, j + 1

    # Fill g2 by trying all possible paths starting from each cell of g2
    for i in range(N):
        for j in range(N):
            if g2[i][j] == 0:
                for (i2, j2, v2) in sorted_grid_values:
                    if (i2, j2, v2) != (x, y, g2[i][j]):
                        g2[i][j] = g2[i2][j2] + v2
                        break

    # Initialize variables to keep track of the maximum sums
    max_sum1 = 0
    max_sum2 = 0
    max_index = 0

    # Check all cells in grid2 to find the cell with the maximum sum
    for i in range(N):
        for j in range(N):
            if g2[i][j] > max_sum1:
                max_sum1 = g2[i][j]
                max_index = (i, j)

    # Calculate the two paths by starting from the maximum index
    path1 = []
    for k in range(max_index[0], -1, -1):
        for l in range(max_index[1], -1, -1):
            if grid_values[(k, l, g2[k][l])] == grid_values[max_index]:
                path1.append(grid_values[(k, l, g2[k][l])])
                break

    path2 = []
    for k in range(max_index[0] + 1, N):
        for l in range(max_index[1] + 1, N):
            if grid_values[(k, l, g2[k][l])] == grid_values[max_index]:
                path2.append(grid_values[(k, l, g2[k][l])])
                break

    # Return the maximum sum of values collected on the two paths
    return max_sum1 + max_sum2
