def count_passing_ways(n: int, m: int) -> int:
    # Initialize a DP array where dp[i][j] represents the number of ways to pass the ball
    # from student j to the starting student (index 0) in exactly i passes
    dp = [[0] * n for _ in range(m + 1)]

    # Base case: if the ball is in the same spot after 0 passes, there is only 1 way
    for i in range(n):
        dp[0][i] = 1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(n):
            # If the ball comes from the left neighbor, it has 2 options: leave it or pass to the right
            if j != 0:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            # If the ball comes from the right neighbor, it has 2 options: leave it or pass to the left
            if j + 1 != n:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j + 1]

    # The number of ways to pass the ball from the last student to the starting student in 'm' passes
    return dp[m][n - 1]
