        root = [root_val]
        left = create_subtree(inorder_start + 1, root_index - 1, postorder_start, postorder_start + left_size - 1)
        right = create_subtree(root_index + 1, inorder_end, postorder_start + left_size, postorder_end - 1)
        root.extend(left)
        root.extend(right)
        return root

