def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14
    else:
        total_moves = 0
        base_move = 4
        for i in range(1, n + 1):
            moves = base_move * (2 ** i - 1)
            total_moves += moves
            base_move *= 3
        return total_moves
```

